---@class oriel.ui
oriel.ui = {}

--- A section drawn by its load's state (widget.Async): { load (an oriel.load handle; started for you), body = fn(value) (returns the loaded section's nodes), policy = inline|block|gate|optional, label (what's loading), loading (nodes to show while it loads; a busy line by default), empty (text shown once loaded when is_empty = fn(value) says so), retry (true shows Retry on a failure), fallback (optional: what's used if the user goes on now), id }.
---@param spec table
---@return table
function oriel.ui.async(spec) end

--- An inline loading line (widget.Busy): a spinner, { label (what's loading; the … is added), load (an oriel.load handle: adds what it's doing and, after clock seconds, how long it's run), clock (3 by default; -1 never), size, color, id }.
---@param spec table
---@return table
function oriel.ui.busy(spec) end

--- A button: { label, on_click = fn(), primary, busy (shows a spinner and can't be pressed: its work is running), busy_label, id }. The id keeps it the same button as the view redraws, where labels repeat or change.
---@param spec table
---@return table
function oriel.ui.button(spec) end

--- A chart (widget.Chart): { kind = bars|area|line|spark|strip, series = { { name, values = { … }, color, kind, dashed, from } }, labels, height, max, y_ticks, format = money|percent|count, legend, hover, marks = { { at, label, color, dashed } }, bands = { { from, to, label } }, on_click = fn(series, point), id, label }. color is a theme token (cyan, accent, stats.kind.output) or #rrggbb; series and points count from 1.
---@param spec table
---@return table
function oriel.ui.chart(spec) end

--- A column of nodes; options beside them: gap, pad (px), and lines as a row's.
---@param children any
---@return table
function oriel.ui.column(children) end

--- A range of days (widget.DatePicker): { from, to, on_change = fn(from, to), placeholder, id, label }. Days are YYYY-MM-DD; a button showing the range opens a calendar under it, where arrows move, Enter picks one end then the other, Esc cancels, and a range can be typed as 2026-09-01..2026-09-30.
---@param spec table
---@return table
function oriel.ui.date_picker(spec) end

--- Someone at work with no known end (widget.Dots): three dots with a wave crossing them, { name (what's going on, read out), color (a theme token or #rrggbb; status.working by default), size (each dot's px across, 5 by default), id }. They hold still with reduced motion.
---@param spec table
---@return table
function oriel.ui.dots(spec) end

--- An indicator: { label, value, bar (0 to 1), warn (the bar's warning level), tone (ok, warn, error), dot (a status dot before the value: ok, warn, error, accent, dim), id }.
---@param spec table
---@return table
function oriel.ui.indicator(spec) end

--- A text field: { value, placeholder, on_change = fn(text), on_submit = fn(text), id, label, lines, enter_submits }: lines > 1 takes several lines (⏎ a new line, ⌘⏎ submits; with enter_submits, a message's: ⏎ submits, ⇧⏎ a new line). Keep the text in oriel.ui.state and give it back as value.
---@param spec table
---@return table
function oriel.ui.input(spec) end

--- A list: each of items through row(item), which returns a node.
---@param items any
---@param row function
---@return table
function oriel.ui.list(items, row) end

--- The editor's mode, as the built-in status line shows it.
---@return table
function oriel.ui.mode() end

--- A loading bar (widget.ProgressBar): { value (0 to 1; nil slides back and forth with no known end), height (px, 4 by default; 6 or more shows the label above it), label, color, id }.
---@param spec table
---@return table
function oriel.ui.progress(spec) end

--- A dial (widget.Ring): { value (0 to 1 of the ring lit, clockwise from twelve o'clock), label (in the middle: '18m'), color (a theme token or #rrggbb; the accent by default), size (px across, 44 by default), name (what it measures, read out with the label), id }.
---@param spec table
---@return table
function oriel.ui.ring(spec) end

--- A row of nodes; options beside them: gap, pad (px), and in a presenter's block lines = { from, to } (a part of the block on those source lines, 1-based: selected, commented on and given its threads on its own). Any node can be dragged (drag = { kind, data, label }) or take drops (accepts = { kinds }, on_drop = fn(kind, data); a 'file' drop's data is its paths).
---@param children any
---@return table
function oriel.ui.row(children) end

--- A menu of choices: { value, options = { … }, on_change = fn(value), id, label }.
---@param spec table
---@return table
function oriel.ui.select(spec) end

--- Grey placeholders in the shape of what's coming (widget.Skeleton): { rows (text-like bars), widths = { 1, 0.8, 0.6 } (each row's share of the width, repeating), block = { w, h } (a card-shaped block in place of rows), count (how many blocks), direction = row|column, label, id }.
---@param spec table
---@return table
function oriel.ui.skeleton(spec) end

--- Space that takes what's left.
---@return table
function oriel.ui.spacer() end

--- Something in progress with no known end (widget.Spinner): { name (what's in progress, read out), color (a theme token or #rrggbb; the accent by default), size (px across, 14 by default), id }. It holds still with reduced motion.
---@param spec table
---@return table
function oriel.ui.spinner(spec) end

--- A table kept by key across redraws and calls, made from initial the first time: a view's own state. Include ctx.instance in the key for one per instance.
---@param key string
---@param initial? any
---@return table
function oriel.ui.state(key, initial) end

--- Text, in a style: dim, faint, accent, warn, error, ok, or title (larger and bold: a heading, a meeting's name).
---@param s any
---@param style? string
---@return table
function oriel.ui.text(s, style) end

--- An on/off switch: { on, on_change = fn(on), id, label }.
---@param spec table
---@return table
function oriel.ui.toggle(spec) end

---@class oriel.view
oriel.view = {}

--- Register a view under id, replacing any of that id (a built-in panel, the status line): fn(ctx) returns oriel.ui nodes.
---@param id string
---@param fn function
function oriel.view.override(id, fn) end

---@class oriel.wasm
oriel.wasm = {}

--- Load a WASM module: path is the plugin's own .wasm (relative to its directory: no grant needed), or a file its fs.read grant covers. It runs in wazero with no way out but the host functions it imports from oriel (request, notify, log), each checked against the plugin's grants. opts: on = { method = fn(params) } answering its requests before the host. Returns a module: mod:call(fn, ...) with numbers, mod:request(fn, value) with JSON (the ABI in plugins.md), mod:exports(), mod:close().
---@param path string
---@param opts? table
---@return table
function oriel.wasm.load(path, opts) end

